import app from 'flarum/forum/app';
import m from 'mithril';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import stringToColor from 'flarum/common/utils/stringToColor';
import { peopleToday } from '../today';
import { t } from '../util';
import { claim, release, hosted } from '../hosts';

/** A birthday or an anniversary today. */

const fanfare = () => app.data.fanfare;

/**
 * Today's birthdays and join anniversaries, and who finished a course lately,
 * with a one-tap wish (Congratulate, for a course).
 *
 * host: 'sidebar' (the index sidebar), 'strip' (chips above the discussion
 * list: on phones, and on wide screens whenever the sidebar copy isn't
 * visible, as under Bespoke), or a widget host the admin placed it in
 * ('bespoke', 'fof'). A placed copy makes the two fallbacks stand down.
 */
export default class Widget extends Component {
  wide = false;
  busy = false;
  oncreate(vnode) {
    super.oncreate(vnode);
    if (!this.fallback()) claim(this.attrs.host);
    this.measure();
  }
  onupdate(vnode) {
    super.onupdate(vnode);
    this.measure();
  }
  onremove(vnode) {
    super.onremove(vnode);
    if (!this.fallback()) release(this.attrs.host);
    if (this.scrollCue) window.removeEventListener('resize', this.scrollCue);
  }
  fallback() {
    return this.attrs.host === 'sidebar' || this.attrs.host === 'strip';
  }

  /**
   * The strip shows on wide screens too when the sidebar copy is not on screen,
   * and fades at the right while more chips are out of view.
   */
  measure() {
    if (this.attrs.host !== 'strip') return;
    const side = document.querySelector('.FanfareWidget--sidebar');
    const wanted = !side || !side.offsetParent;
    if (wanted !== !!this.wide) {
      this.wide = wanted;
      m.redraw();
    }
    const el = this.element;
    if (!el) return;
    if (!this.scrollCue) {
      this.scrollCue = () => el.classList.toggle('is-more', el.scrollLeft + el.clientWidth < el.scrollWidth - 4);
      el.addEventListener('scroll', this.scrollCue, {
        passive: true
      });
      window.addEventListener('resize', this.scrollCue);
    }
    this.scrollCue();
  }
  view() {
    const data = fanfare();
    const today = peopleToday(data);
    const strip = this.attrs.host === 'strip';
    const courses = data.courses?.list || [];
    if (!today.birthdays.length && !today.anniversaries.length && !courses.length || this.fallback() && hosted()) return null;
    return m("section", {
      className: 'FanfareWidget FanfareWidget--' + this.attrs.host + (strip && this.wide ? ' is-wide' : ''),
      "aria-label": t('widget.heading')
    }, today.birthdays.length ? group('🎂', strip ? t('widget.today') : t('widget.heading'), this.rows(today.birthdays, 'birthday', strip), more(data.people.more.birthdays, strip)) : null, today.anniversaries.length ? group('🏅', t('widget.anniversaries'), this.rows(today.anniversaries, 'anniversary', strip), more(data.people.more.anniversaries, strip)) : null, courses.length ? group('🎓', t('widget.courses'), courses.map(c => this.courseRow(c, strip)), more(data.courses.more, strip)) : null);
  }

  /** Today's birthdays or anniversaries: each person, and a wish for them. */
  rows(list, kind, strip) {
    const data = fanfare();
    return list.map(p => {
      const u = data.people?.users[p.id];
      if (!u) return null;
      const sub = kind === 'birthday' ? p.age ? t('widget.turns', {
        age: p.age
      }) : null : t('widget.years', {
        count: p.years
      });
      return m("div", {
        className: "FanfareWidget-row",
        key: kind + p.id
      }, m(Link, {
        href: app.route('user', {
          username: u.slug
        }),
        className: "FanfareWidget-person"
      }, avatar(u), m("span", {
        className: "FanfareWidget-who"
      }, m("span", {
        className: "FanfareWidget-name"
      }, u.name), sub && !strip ? m("span", {
        className: "FanfareWidget-sub"
      }, sub) : null)), this.wishButton(p.id, kind, u.name));
    });
  }

  /** Who finished a course: the course links to its certificate's public page. */
  courseRow(c, strip) {
    const u = fanfare().courses.users[c.user];
    if (!u) return null;
    const title = c.url ? m("a", {
      href: c.url,
      className: "FanfareWidget-sub FanfareWidget-course"
    }, c.title) : m("span", {
      className: "FanfareWidget-sub"
    }, c.title);
    return m("div", {
      className: "FanfareWidget-row",
      key: 'course' + c.id
    }, m("span", {
      className: "FanfareWidget-person"
    }, m(Link, {
      href: app.route('user', {
        username: u.slug
      })
    }, avatar(u)), m("span", {
      className: "FanfareWidget-who"
    }, m(Link, {
      href: app.route('user', {
        username: u.slug
      }),
      className: "FanfareWidget-name"
    }, u.name), strip ? null : title)), this.wishButton(c.user, 'course', u.name, c.id));
  }

  /** ref: the course completion a Congratulate is for. */
  wishButton(id, kind, name, ref) {
    const data = fanfare();
    if (!data.canWish || Number(app.session.user?.id()) === id) return null;
    const key = kind + ':' + (kind === 'course' ? ref : id);
    if ((data.wished || []).includes(key)) {
      return m("span", {
        className: "FanfareWidget-wished"
      }, m("i", {
        className: "fas fa-check",
        "aria-hidden": "true"
      }), " ", t(kind === 'course' ? 'widget.congratulated' : 'widget.wished'));
    }
    return m("button", {
      type: "button",
      className: "Button Button--flat FanfareWidget-wish",
      "aria-label": t(kind === 'course' ? 'widget.congratulate_label' : 'widget.wish_label', {
        name
      }),
      disabled: this.busy,
      onclick: () => this.wish(id, kind, name, ref, key)
    }, "\uD83C\uDF89 ", t(kind === 'course' ? 'widget.congratulate' : 'widget.wish'));
  }
  wish(id, kind, name, ref, key) {
    this.busy = true;
    app.request({
      method: 'POST',
      url: app.forum.attribute('apiUrl') + '/fanfare-wishes',
      body: {
        data: {
          type: 'fanfare-wishes',
          attributes: {
            userId: id,
            kind,
            achievementId: ref ?? null
          }
        }
      }
    }).then(() => {
      const data = fanfare();
      data.wished = [...(data.wished || []), key];
      app.alerts.show({
        type: 'success'
      }, t(kind === 'course' ? 'widget.congratulate_sent' : 'widget.wish_sent', {
        name
      }));
    }).finally(() => {
      this.busy = false;
      m.redraw();
    });
  }
}

/** A group of the widget: its heading, its rows and how many more there are. */
function group(emoji, heading, rows, rest) {
  return m("div", {
    className: "FanfareWidget-group"
  }, m("h4", {
    className: "FanfareWidget-heading"
  }, emoji + ' ', heading), rows, rest);
}
function more(n, strip) {
  return n > 0 && !strip ? m("div", {
    className: "FanfareWidget-more"
  }, t('widget.more', {
    count: n
  })) : null;
}
function avatar(u) {
  return u.avatar ? m("img", {
    className: "Avatar FanfareWidget-avatar",
    src: u.avatar,
    alt: "",
    loading: "lazy"
  }) : m("span", {
    className: "Avatar FanfareWidget-avatar",
    style: {
      '--avatar-bg': '#' + stringToColor(u.username)
    },
    "aria-hidden": "true"
  }, (u.name || u.username || '?').charAt(0).toUpperCase());
}
flarum.reg.add('ernestdefoe-fanfare', 'forum/components/Widget', Widget);